import{_ as a,o as t,c as s,a5 as e}from"./chunks/framework.a5no_H3L.js";const n="/unity/02-unity-scripting-chapter-04-inspector-fields.png",y=JSON.parse('{"title":"Unity 的 C# 约定：序列化与 Inspector","description":"你在脚本里写的 public float speed 会出现在 Inspector 里，还能拖拽赋值。读完这一篇，你能说清 Unity 的序列化规则：哪些字段会显示在 Inspector、怎么控制显示、哪些类型能序列化，以及这个机制为什么重要。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"unity/02-unity-scripting/chapter-04-serialization-inspector.md","filePath":"unity/02-unity-scripting/chapter-04-serialization-inspector.md"}'),r={name:"unity/02-unity-scripting/chapter-04-serialization-inspector.md"};function c(p,i,l,o,d,h){return t(),s("div",null,[...i[0]||(i[0]=[e(`<h1 id="unity-的-c-约定-序列化与-inspector" tabindex="-1" data-src-line="2" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">Unity 的 C# 约定：序列化与 Inspector <a class="header-anchor" href="#unity-的-c-约定-序列化与-inspector" aria-label="Permalink to &quot;Unity 的 C# 约定：序列化与 Inspector&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">你在脚本里写的 <code>public float speed</code> 会出现在 Inspector 里，还能拖拽赋值。读完这一篇，你能说清 Unity 的序列化规则：哪些字段会显示在 Inspector、怎么控制显示、哪些类型能序列化，以及这个机制为什么重要。</p><h2 id="_1-inspector-为什么会显示字段" tabindex="-1" data-src-line="6" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">1. Inspector 为什么会显示字段 <a class="header-anchor" href="#_1-inspector-为什么会显示字段" aria-label="Permalink to &quot;1. Inspector 为什么会显示字段&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">Unity 有个叫<strong>序列化（Serialization）</strong> 的机制：把脚本里符合规则的字段保存到磁盘，并在 Inspector 里显示出来供你编辑。</p><p data-src-line="10" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">当你写：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PlayerMovement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MonoBehaviour</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> float</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> speed</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p data-src-line="19" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md"><code>speed</code> 是 public 字段，Unity 会把它序列化，于是 Inspector 里出现一个 <code>Speed</code> 输入框。你在编辑器里把 5 改成 10，运行时 <code>speed</code> 就是 10，<strong>覆盖了脚本里的默认值</strong>。</p><p data-src-line="21" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md"><img src="`+n+`" alt="Inspector 里显示脚本组件的序列化字段：Example (Script) 下的 My Name 是可编辑字段"></p><p data-src-line="23" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md"><em>图源：<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/script-Serialization.html" target="_blank" rel="noreferrer">Unity 官方文档</a></em></p><p data-src-line="25" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">这带来一个好处：调参不用改代码。移动速度、跳跃力度、血量这些&quot;希望美术或策划也能调&quot;的数值，暴露到 Inspector 里，改完立刻看效果。</p><h2 id="_2-控制字段是否显示" tabindex="-1" data-src-line="27" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">2. 控制字段是否显示 <a class="header-anchor" href="#_2-控制字段是否显示" aria-label="Permalink to &quot;2. 控制字段是否显示&quot;">​</a></h2><h3 id="_2-1-public-字段-默认显示" tabindex="-1" data-src-line="29" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">2.1 public 字段：默认显示 <a class="header-anchor" href="#_2-1-public-字段-默认显示" aria-label="Permalink to &quot;2.1 public 字段：默认显示&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> float</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> speed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 显示在 Inspector</span></span></code></pre></div><h3 id="_2-2-私有字段-用-serializefield-显示" tabindex="-1" data-src-line="35" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">2.2 私有字段：用 [SerializeField] 显示 <a class="header-anchor" href="#_2-2-私有字段-用-serializefield-显示" aria-label="Permalink to &quot;2.2 私有字段：用 [SerializeField] 显示&quot;">​</a></h3><p data-src-line="37" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">只想在 Inspector 里调、不想让其他类随便改，用私有字段加特性：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SerializeField</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> float</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> speed</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 私有，但仍显示在 Inspector</span></span></code></pre></div><p data-src-line="44" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">这是推荐做法：默认用 <code>private</code> + <code>[SerializeField]</code>，只有确实需要被其他类访问的字段才用 <code>public</code>。它兼顾了封装（外部不能随意改）和可调性（Inspector 能调）。</p><h3 id="_2-3-用-hideininspector-隐藏-public-字段" tabindex="-1" data-src-line="46" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">2.3 用 [HideInInspector] 隐藏 public 字段 <a class="header-anchor" href="#_2-3-用-hideininspector-隐藏-public-字段" aria-label="Permalink to &quot;2.3 用 [HideInInspector] 隐藏 public 字段&quot;">​</a></h3><p data-src-line="48" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">反过来，public 字段不想显示，加 <code>[HideInInspector]</code>：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HideInInspector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> float</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cache</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 对外公开，但不出现在 Inspector</span></span></code></pre></div><h2 id="_3-哪些类型能被序列化" tabindex="-1" data-src-line="55" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">3. 哪些类型能被序列化 <a class="header-anchor" href="#_3-哪些类型能被序列化" aria-label="Permalink to &quot;3. 哪些类型能被序列化&quot;">​</a></h2><p data-src-line="57" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">不是所有字段都能在 Inspector 里显示。Unity 支持序列化的类型包括：</p><ul data-src-line="59" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md"><li data-src-line="59" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">基础类型：<code>int</code>、<code>float</code>、<code>bool</code>、<code>string</code>、<code>double</code> 等。</li><li data-src-line="60" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">Unity 结构体：<code>Vector2</code>、<code>Vector3</code>、<code>Color</code>、<code>Quaternion</code>。</li><li data-src-line="61" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">引用类型：<code>GameObject</code>、<code>Transform</code>、<code>MonoBehaviour</code>、<code>ScriptableObject</code> 等（可在 Inspector 里拖拽赋值）。</li><li data-src-line="62" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">上述类型的<strong>数组</strong>和 <code>List&lt;T&gt;</code>。</li></ul><p data-src-line="64" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md"><strong>不能序列化</strong>的常见情况：</p><ul data-src-line="66" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md"><li data-src-line="66" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md"><code>Dictionary&lt;TKey, TValue&gt;</code>：不支持，需要额外处理。</li><li data-src-line="67" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">属性（Property）：<code>public float Speed { get; set; }</code> 不会显示，只有字段（field）才序列化。</li><li data-src-line="68" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md"><code>static</code> 字段：属于类型而非实例，不序列化。</li><li data-src-line="69" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">自定义类默认不序列化，除非加上 <code>[System.Serializable]</code>。</li></ul><h2 id="_4-inspector-里拖拽赋值-引用类型" tabindex="-1" data-src-line="71" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">4. Inspector 里拖拽赋值：引用类型 <a class="header-anchor" href="#_4-inspector-里拖拽赋值-引用类型" aria-label="Permalink to &quot;4. Inspector 里拖拽赋值：引用类型&quot;">​</a></h2><p data-src-line="73" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">引用类型字段最有用的是<strong>拖拽赋值</strong>。例如：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SerializeField</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GameObject</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> player</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p data-src-line="80" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">Inspector 里会出现一个 <code>Player</code> 槽位，把场景里的玩家物体拖进去，脚本里就能用 <code>player</code> 引用它，而不需要写 <code>GameObject.Find</code>。这比运行时查找更直观、更快、更不易出错。</p><h2 id="_5-序列化的另一个作用-场景保存" tabindex="-1" data-src-line="82" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">5. 序列化的另一个作用：场景保存 <a class="header-anchor" href="#_5-序列化的另一个作用-场景保存" aria-label="Permalink to &quot;5. 序列化的另一个作用：场景保存&quot;">​</a></h2><p data-src-line="84" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">序列化不只是&quot;显示在 Inspector&quot;。你在 Inspector 里改的数值、拖进去的引用，都会随<strong>场景文件</strong>一起保存。下次打开项目，这些值还在。</p><p data-src-line="86" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">这也解释了为什么&quot;运行时改的值不会保存&quot;：你在 Play 模式下改 Inspector 数值，退出 Play 后会恢复。因为运行时修改的是内存里的副本，没有写回场景文件。要在运行中持久化数据，需要用 <a href="./../05-engineering/chapter-03-data-persistence.html">数据持久化</a> 里的手段。</p><h2 id="_6-动手验证" tabindex="-1" data-src-line="88" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">6. 动手验证 <a class="header-anchor" href="#_6-动手验证" aria-label="Permalink to &quot;6. 动手验证&quot;">​</a></h2><ol data-src-line="90" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md"><li data-src-line="90" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">打开之前的 <code>PlayerMovement</code> 脚本，把 <code>speed</code> 改成 <code>[SerializeField] private float speed = 5f;</code>。</li><li data-src-line="91" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">回到编辑器，等脚本编译完成，看 Inspector 里 <code>Speed</code> 输入框仍然在。</li><li data-src-line="92" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">在 Play 前把 Speed 改成 10，运行后物体移动明显变快。</li><li data-src-line="93" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">退出 Play，把 Speed 改成 2 再运行，验证 Inspector 的值确实在覆盖脚本默认值。</li></ol><h2 id="_7-下一步" tabindex="-1" data-src-line="95" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">7. 下一步 <a class="header-anchor" href="#_7-下一步" aria-label="Permalink to &quot;7. 下一步&quot;">​</a></h2><p data-src-line="97" data-src-file="unity/02-unity-scripting/chapter-04-serialization-inspector.md">到这里，「Unity 脚本基础」结束。你已经会写脚本、读输入、调参数。下一篇进入核心概念，理解场景和坐标系统：<a href="./../03-scene-core/chapter-01-scene-transform.html">场景、坐标系与 Transform</a>。</p>`,36)])])}const k=a(r,[["render",c]]);export{y as __pageData,k as default};
